import { applyFilter, peakingFilter } from './filters';

/**
 * Practice sounds, generated by code so the app needs no audio files and works offline.
 * Each is a four-second loop at 120 beats per minute, built to make one thing easy to hear:
 * uneven notes for a compressor, or bleed between hits for a gate.
 * They are deliberately simple and sound like a drum machine and a synth, not like a band.
 */

export const PRACTICE_SAMPLE_RATE = 44100;

const LOOP_SECONDS = 4;
const BEAT_SECONDS = 0.5;
const TARGET_PEAK = 0.7;
const TWO_PI = Math.PI * 2;

export type PracticeSoundId =
  | 'drumLoop'
  | 'unevenBass'
  | 'unevenVoice'
  | 'snareWithBleed'
  | 'kickWithBleed'
  | 'voiceWithRumble'
  | 'fullMix'
  | 'muddyMix'
  | 'voiceHarshWhenLoud'
  | 'voiceWithSharpS';

export type PracticeUse = 'compressor' | 'gate' | 'eq' | 'dynamicEq';

export interface PracticeSound {
  id: PracticeSoundId;
  label: string;
  description: string;
  bestFor: PracticeUse;
}

export const PRACTICE_SOUNDS: PracticeSound[] = [
  { id: 'unevenBass', label: 'Bass with uneven notes', description: 'Some notes are plucked much harder than others. Use the compressor to even them out.', bestFor: 'compressor' },
  { id: 'unevenVoice', label: 'Synth "voice", quiet then loud', description: 'A quiet phrase followed by a loud one. Listen to how the compressor brings them together.', bestFor: 'compressor' },
  { id: 'drumLoop', label: 'Drum loop', description: 'Kick, snare and hi-hat. The clearest place to hear attack and release.', bestFor: 'compressor' },
  { id: 'snareWithBleed', label: 'Snare mic with bleed', description: 'Snare hits with hi-hat and kick leaking in between. Use the gate to clean up the gaps.', bestFor: 'gate' },
  { id: 'kickWithBleed', label: 'Kick mic with bleed', description: 'Kick hits, one of them soft, with snare leaking in. Find a threshold that keeps the soft hit.', bestFor: 'gate' },
  { id: 'voiceWithRumble', label: 'Voice with rumble and thumps', description: 'A voice with low rumble under it and a thump at the start of each phrase. Use the low cut.', bestFor: 'eq' },
  { id: 'muddyMix', label: 'Muddy mix', description: 'Drums, bass and voice with too much low-mid. Find the mud with a cut and sweep it.', bestFor: 'eq' },
  { id: 'fullMix', label: 'Full mix', description: 'Drums, bass and voice together, untreated. For trying shelves and bands.', bestFor: 'eq' },
  { id: 'voiceHarshWhenLoud', label: 'Voice that turns harsh when loud', description: 'The quiet phrase is fine; the loud phrase is harsh around 3 kHz. A fixed EQ cut would dull both.', bestFor: 'dynamicEq' },
  { id: 'voiceWithSharpS', label: 'Voice with sharp "s" sounds', description: 'Bursts of hiss between the notes, like sharp "s" sounds.', bestFor: 'dynamicEq' },
];

/** A small seeded random number generator, so the noise is the same every time. */
function createRandom(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let mixed = Math.imul(state ^ (state >>> 15), 1 | state);
    mixed = (mixed + Math.imul(mixed ^ (mixed >>> 7), 61 | mixed)) ^ mixed;
    return ((mixed ^ (mixed >>> 14)) >>> 0) / 4294967296;
  };
}

function createLoop(sampleRate: number): Float32Array {
  return new Float32Array(Math.round(LOOP_SECONDS * sampleRate));
}

function normalize(samples: Float32Array): Float32Array {
  let peak = 0;
  for (const sample of samples) {
    peak = Math.max(peak, Math.abs(sample));
  }
  if (peak === 0) {
    return samples;
  }
  const scale = TARGET_PEAK / peak;
  for (let index = 0; index < samples.length; index = index + 1) {
    samples[index] = samples[index] * scale;
  }
  return samples;
}

interface Hit {
  beat: number;
  level: number;
}

function addKick(target: Float32Array, sampleRate: number, hit: Hit): void {
  const start = Math.round(hit.beat * BEAT_SECONDS * sampleRate);
  const length = Math.round(0.3 * sampleRate);
  let phase = 0;
  for (let offset = 0; offset < length && start + offset < target.length; offset = offset + 1) {
    const time = offset / sampleRate;
    // The pitch drops quickly from a click to a low thump.
    const frequency = 48 + 110 * Math.exp(-time * 35);
    phase = phase + (TWO_PI * frequency) / sampleRate;
    const body = Math.sin(phase) * Math.exp(-time * 14);
    const click = Math.exp(-time * 400) * 0.5;
    target[start + offset] += (body + click) * hit.level;
  }
}

function addSnare(target: Float32Array, sampleRate: number, hit: Hit, random: () => number): void {
  const start = Math.round(hit.beat * BEAT_SECONDS * sampleRate);
  const length = Math.round(0.22 * sampleRate);
  let previousNoise = 0;
  for (let offset = 0; offset < length && start + offset < target.length; offset = offset + 1) {
    const time = offset / sampleRate;
    const noise = random() * 2 - 1;
    // The difference between neighbouring noise samples keeps only the bright part.
    const brightNoise = noise - previousNoise * 0.6;
    previousNoise = noise;
    const rattle = brightNoise * Math.exp(-time * 22) * 0.6;
    const drum = Math.sin(TWO_PI * 190 * time) * Math.exp(-time * 30) * 0.7;
    target[start + offset] += (rattle + drum) * hit.level;
  }
}

function addHiHat(target: Float32Array, sampleRate: number, hit: Hit, random: () => number): void {
  const start = Math.round(hit.beat * BEAT_SECONDS * sampleRate);
  const length = Math.round(0.06 * sampleRate);
  let previousNoise = 0;
  for (let offset = 0; offset < length && start + offset < target.length; offset = offset + 1) {
    const time = offset / sampleRate;
    const noise = random() * 2 - 1;
    const brightNoise = noise - previousNoise;
    previousNoise = noise;
    target[start + offset] += brightNoise * Math.exp(-time * 70) * 0.35 * hit.level;
  }
}

function addNoiseFloor(target: Float32Array, level: number, random: () => number): void {
  for (let index = 0; index < target.length; index = index + 1) {
    target[index] += (random() * 2 - 1) * level;
  }
}

const KICK_PATTERN: Hit[] = [
  { beat: 0, level: 1 },
  { beat: 2, level: 0.9 },
  { beat: 3.5, level: 0.55 },
  { beat: 4, level: 1 },
  { beat: 6, level: 0.95 },
  { beat: 6.5, level: 0.5 },
];

const SNARE_PATTERN: Hit[] = [
  { beat: 1, level: 0.9 },
  { beat: 3, level: 1 },
  { beat: 5, level: 0.55 },
  { beat: 7, level: 1 },
];

function buildHatPattern(): Hit[] {
  const hits: Hit[] = [];
  for (let eighth = 0; eighth < 16; eighth = eighth + 1) {
    const onTheBeat = eighth % 2 === 0;
    hits.push({ beat: eighth / 2, level: onTheBeat ? 1 : 0.6 });
  }
  return hits;
}

function generateDrumLoop(sampleRate: number): Float32Array {
  const loop = createLoop(sampleRate);
  const random = createRandom(11);
  KICK_PATTERN.forEach((hit) => addKick(loop, sampleRate, hit));
  SNARE_PATTERN.forEach((hit) => addSnare(loop, sampleRate, hit, random));
  buildHatPattern().forEach((hit) => addHiHat(loop, sampleRate, hit, random));
  return normalize(loop);
}

function generateSnareWithBleed(sampleRate: number): Float32Array {
  const loop = createLoop(sampleRate);
  const random = createRandom(23);
  SNARE_PATTERN.forEach((hit) => addSnare(loop, sampleRate, hit, random));
  // Bleed: the other drums are heard in this mic too, much quieter.
  KICK_PATTERN.forEach((hit) => addKick(loop, sampleRate, { beat: hit.beat, level: hit.level * 0.18 }));
  buildHatPattern().forEach((hit) => addHiHat(loop, sampleRate, { beat: hit.beat, level: hit.level * 0.45 }, random));
  addNoiseFloor(loop, 0.004, random);
  return normalize(loop);
}

function generateKickWithBleed(sampleRate: number): Float32Array {
  const loop = createLoop(sampleRate);
  const random = createRandom(37);
  KICK_PATTERN.forEach((hit) => addKick(loop, sampleRate, hit));
  SNARE_PATTERN.forEach((hit) => addSnare(loop, sampleRate, { beat: hit.beat, level: hit.level * 0.14 }, random));
  addNoiseFloor(loop, 0.003, random);
  return normalize(loop);
}

/** Bass notes with very different pluck strengths: the classic reason for a compressor. */
function generateUnevenBass(sampleRate: number): Float32Array {
  const loop = createLoop(sampleRate);
  const noteFrequencies = [55, 55, 65.4, 55, 73.4, 73.4, 65.4, 49];
  const noteLevels = [1, 0.4, 0.85, 0.3, 1, 0.55, 0.35, 0.9];
  const noteLength = Math.round(BEAT_SECONDS * sampleRate);

  for (let note = 0; note < noteFrequencies.length; note = note + 1) {
    const start = note * noteLength;
    const frequency = noteFrequencies[note];
    for (let offset = 0; offset < noteLength && start + offset < loop.length; offset = offset + 1) {
      const time = offset / sampleRate;
      // A few harmonics that die away faster the higher they are, like a plucked string.
      let sample = 0;
      for (let harmonic = 1; harmonic <= 6; harmonic = harmonic + 1) {
        const harmonicLevel = (1 / harmonic) * Math.exp(-time * harmonic * 2.2);
        sample = sample + Math.sin(TWO_PI * frequency * harmonic * time) * harmonicLevel;
      }
      const fadeIn = Math.min(1, time / 0.004);
      const fadeOut = Math.min(1, (noteLength - offset) / (0.02 * sampleRate));
      loop[start + offset] += sample * fadeIn * fadeOut * noteLevels[note];
    }
  }
  return normalize(loop);
}

/** A sung-vowel-like tone: a quiet phrase, a gap, then a loud phrase. */
function generateUnevenVoice(sampleRate: number): Float32Array {
  const loop = createLoop(sampleRate);
  const phrases = [
    { startSeconds: 0.1, endSeconds: 1.7, level: 0.28, pitch: 196 },
    { startSeconds: 2.1, endSeconds: 3.8, level: 1, pitch: 262 },
  ];
  const formants = [700, 1150, 2600];

  for (const phrase of phrases) {
    const start = Math.round(phrase.startSeconds * sampleRate);
    const end = Math.round(phrase.endSeconds * sampleRate);
    let phase = 0;
    for (let index = start; index < end && index < loop.length; index = index + 1) {
      const time = (index - start) / sampleRate;
      const vibrato = 1 + 0.008 * Math.sin(TWO_PI * 5.5 * time);
      phase = phase + (TWO_PI * phrase.pitch * vibrato) / sampleRate;

      let sample = 0;
      for (let harmonic = 1; harmonic <= 14; harmonic = harmonic + 1) {
        const harmonicFrequency = phrase.pitch * harmonic;
        // Harmonics near a formant are louder, which is what makes a tone sound like a vowel.
        let formantLevel = 0.05;
        for (const formant of formants) {
          const distance = (harmonicFrequency - formant) / 180;
          formantLevel = formantLevel + Math.exp(-distance * distance);
        }
        sample = sample + (Math.sin(phase * harmonic) * formantLevel) / harmonic;
      }

      const sinceStart = time;
      const untilEnd = (end - index) / sampleRate;
      const envelope = Math.min(1, sinceStart / 0.06) * Math.min(1, untilEnd / 0.12);
      // A slow swell inside the phrase, as a singer would do.
      const swell = 0.8 + 0.2 * Math.sin(TWO_PI * 0.6 * time);
      loop[index] += sample * envelope * swell * phrase.level;
    }
  }
  return normalize(loop);
}

function mixTogether(parts: { samples: Float32Array; level: number }[]): Float32Array {
  const mixed = new Float32Array(parts[0].samples.length);
  for (const part of parts) {
    for (let index = 0; index < mixed.length; index = index + 1) {
      mixed[index] += part.samples[index] * part.level;
    }
  }
  return mixed;
}

function generateFullMix(sampleRate: number): Float32Array {
  const mixed = mixTogether([
    { samples: generateDrumLoop(sampleRate), level: 0.8 },
    { samples: generateUnevenBass(sampleRate), level: 0.7 },
    { samples: generateUnevenVoice(sampleRate), level: 0.9 },
  ]);
  return normalize(mixed);
}

/** The full mix with a wide hump around 280 Hz, the "mud" range. */
function generateMuddyMix(sampleRate: number): Float32Array {
  const hump = peakingFilter(280, 9, 1.2, sampleRate);
  return normalize(applyFilter(generateFullMix(sampleRate), hump));
}

/** A voice with steady low rumble under it and a low thump as each phrase starts. */
function generateVoiceWithRumble(sampleRate: number): Float32Array {
  const voice = generateUnevenVoice(sampleRate);
  const random = createRandom(51);
  const rumble = new Float32Array(voice.length);
  let slowNoise = 0;
  for (let index = 0; index < rumble.length; index = index + 1) {
    const time = index / sampleRate;
    // Heavily smoothed noise is low rumble; the 50 Hz tone is mains hum.
    slowNoise = slowNoise * 0.995 + (random() * 2 - 1) * 0.005;
    rumble[index] = slowNoise * 6 + Math.sin(TWO_PI * 50 * time) * 0.12;
  }
  const thumps = new Float32Array(voice.length);
  addKick(thumps, sampleRate, { beat: 0.2, level: 0.5 });
  addKick(thumps, sampleRate, { beat: 4.2, level: 0.7 });
  return normalize(mixTogether([{ samples: voice, level: 1 }, { samples: rumble, level: 1 }, { samples: thumps, level: 1 }]));
}

/** The loud phrase has a strong peak around 3 kHz; the quiet phrase does not. */
function generateVoiceHarshWhenLoud(sampleRate: number): Float32Array {
  const voice = generateUnevenVoice(sampleRate);
  const harsh = applyFilter(voice, peakingFilter(3000, 14, 2.5, sampleRate));
  const loudPhraseStart = Math.round(2.0 * sampleRate);
  const mixed = new Float32Array(voice.length);
  for (let index = 0; index < mixed.length; index = index + 1) {
    mixed[index] = index < loudPhraseStart ? voice[index] : harsh[index];
  }
  return normalize(mixed);
}

/** Short bursts of bright hiss on top of the voice, like sharp "s" sounds. */
function generateVoiceWithSharpS(sampleRate: number): Float32Array {
  const voice = generateUnevenVoice(sampleRate);
  // Make both phrases a similar level, so the "s" sounds are the only problem.
  const quietPhraseEnd = Math.round(1.9 * sampleRate);
  for (let index = 0; index < quietPhraseEnd; index = index + 1) {
    voice[index] = voice[index] * 2.6;
  }
  const random = createRandom(67);
  const hiss = new Float32Array(voice.length);
  const burstStarts = [0.55, 1.25, 2.6, 3.3];
  const burstLength = Math.round(0.13 * sampleRate);
  for (const startSeconds of burstStarts) {
    const start = Math.round(startSeconds * sampleRate);
    let previous = 0;
    let beforePrevious = 0;
    for (let offset = 0; offset < burstLength; offset = offset + 1) {
      const noise = random() * 2 - 1;
      // Taking differences twice leaves only the very bright part of the noise.
      const bright = noise - 2 * previous + beforePrevious;
      beforePrevious = previous;
      previous = noise;
      const fade = Math.sin((Math.PI * offset) / burstLength);
      hiss[start + offset] = bright * fade * 0.22;
    }
  }
  return normalize(mixTogether([{ samples: voice, level: 1 }, { samples: hiss, level: 1 }]));
}

export function generatePracticeSound(id: PracticeSoundId, sampleRate: number = PRACTICE_SAMPLE_RATE): Float32Array {
  switch (id) {
    case 'drumLoop':
      return generateDrumLoop(sampleRate);
    case 'unevenBass':
      return generateUnevenBass(sampleRate);
    case 'unevenVoice':
      return generateUnevenVoice(sampleRate);
    case 'snareWithBleed':
      return generateSnareWithBleed(sampleRate);
    case 'kickWithBleed':
      return generateKickWithBleed(sampleRate);
    case 'voiceWithRumble':
      return generateVoiceWithRumble(sampleRate);
    case 'fullMix':
      return generateFullMix(sampleRate);
    case 'muddyMix':
      return generateMuddyMix(sampleRate);
    case 'voiceHarshWhenLoud':
      return generateVoiceHarshWhenLoud(sampleRate);
    case 'voiceWithSharpS':
      return generateVoiceWithSharpS(sampleRate);
  }
}
